corr={'P':'A','Q':'B','R':'C'}
ang={'A':70,'B':50}; ang['C']=180-ang['A']-ang['B']
side={frozenset('AB'):6}
def angle(v): return ang[corr[v]]
def sidelen(s): return side.get(frozenset(corr[c] for c in s))
opts={'A':('QR','R'),'B':('QR','Q'),'C':('QP','P'),'D':('QP','R')}
res={k:(sidelen(s)==6 and angle(a)==60) for k,(s,a) in opts.items()}
assert res['D']
for k in 'ABC': assert not res[k]
